{"role":"gpt","entry":{"code":"# -*- coding: utf-8 -*-\n\"\"\"\nrgon_fix_flashing_and_doctor.py\nWindows / Python 3.9+ / 표준 라이브러리\n\n안전한 진단·정비 범위:\n- 숨김 PowerShell로 프로세스·예약 작업·시작프로그램 조사\n- 명령줄에서 프로젝트 내 지정 스크립트를 정확히 식별한 프로세스만\n  사용자 확인 후 종료\n- 기존 HTML·watcher·bridge 소스는 수정하지 않음\n- 대시보드 바로가기 생성 및 Chrome App 창 1회 실행\n- 구형 큐 파일은 사용자 확인 후 아카이브\n- 승인된 박동·텔레그램 스크립트는 각각 사용자 확인 후 실행\n- 백업·JSON/텍스트 마감 보고서 작성\n\n중요:\n네트워크로 받은 Python을 실행 감시 큐에 적재하는 브릿지나,\n그 브릿지와 연결된 자동 실행 watcher의 수정·숨김 재기동은 수행하지 않습니다.\nast.parse()는 문법 검사일 뿐 코드 실행의 안전성을 보장하지 않습니다.\n프로세스를 숨기는 것만으로 깜빡임 원인이 해결됐다고 보고하지 않습니다.\n\"\"\"\nimport ast\nimport configparser\nimport ctypes\nfrom ctypes import wintypes\nimport datetime\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport urllib.parse\n\n\nROOT = Path(r\"C:\\Users\\sangi\\Downloads\\shin-agent\")\nDASHBOARD = ROOT / \"rgon_alpha_audience.html\"\nSCRIPT_NAMES = {\n    \"rgon_auto_watcher.py\",\n    \"build_omni_link_communicator.py\",\n    \"upgrade_omni_link_v603.py\",\n    \"rgon_bridge_8765.py\",\n    \"rgon_watcher_silent.vbs\",\n}\nPROCESS_NAMES = {\n    \"python.exe\", \"pythonw.exe\", \"wscript.exe\", \"cscript.exe\",\n    \"cmd.exe\", \"powershell.exe\", \"pwsh.exe\",\n}\nSTAMP = datetime.datetime.now().strftime(\"%Y%m%d_%H%M%S_%f\")\nREPORT_DIR = ROOT / \"backups\" / (\"doctor_\" + STAMP)\nNO_WINDOW = 0x08000000\nREPORT = {\n    \"started_at\": datetime.datetime.now().astimezone().isoformat(),\n    \"scope\": \"safe diagnostic and confirmed maintenance\",\n    \"network_code_queue_modified\": False,\n    \"watcher_or_bridge_restarted\": False,\n    \"warnings\": [],\n}\n\n\ndef log(message):\n    print(message, flush=True)\n\n\ndef atomic_write(path, data):\n    if not data:\n        raise RuntimeError(\"R13: 빈 파일 쓰기 차단\")\n    path.parent.mkdir(parents=True, exist_ok=True)\n    descriptor, temporary = tempfile.mkstemp(prefix=\".rgon-doctor-\", dir=str(path.parent))\n    try:\n        with os.fdopen(descriptor, \"wb\") as stream:\n            stream.write(data)\n            stream.flush()\n            os.fsync(stream.fileno())\n        if Path(temporary).read_bytes() != data:\n            raise RuntimeError(\"임시 파일 검증 실패\")\n        os.replace(temporary, path)\n    finally:\n        if os.path.exists(temporary):\n            os.unlink(temporary)\n\n\ndef encoded_json(value):\n    return (json.dumps(value, ensure_ascii=False, indent=2) + \"\\n\").encode(\"utf-8\")\n\n\ndef confirm(message):\n    try:\n        return input(message + \" [Y/N, 기본 N]: \").strip().upper() == \"Y\"\n    except (EOFError, KeyboardInterrupt):\n        return False\n\n\ndef hidden_options():\n    info = subprocess.STARTUPINFO()\n    info.dwFlags |= subprocess.STARTF_USESHOWWINDOW\n    info.wShowWindow = 0\n    return {\"startupinfo\": info, \"creationflags\": NO_WINDOW}\n\n\ndef run_hidden(arguments, timeout=60, cwd=None):\n    # shell=True, 임의 문자열 명령, 수거 코드 실행을 사용하지 않는다.\n    return subprocess.run(\n        [str(value) for value in arguments],\n        cwd=str(cwd or ROOT),\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.PIPE,\n        timeout=timeout,\n        **hidden_options(),\n    )\n\n\ndef powershell_exe():\n    candidate = Path(os.environ.get(\"SystemRoot\", r\"C:\\Windows\")) / (\n        \"System32/WindowsPowerShell/v1.0/powershell.exe\"\n    )\n    if not candidate.is_file():\n        raise RuntimeError(\"Windows PowerShell을 찾을 수 없습니다.\")\n    return candidate\n\n\ndef powershell(source, timeout=60):\n    prefix = (\n        \"$ErrorActionPreference='Stop';\"\n        \"[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false);\"\n    )\n    result = run_hidden([\n        powershell_exe(), \"-NoLogo\", \"-NoProfile\", \"-NonInteractive\",\n        \"-WindowStyle\", \"Hidden\", \"-Command\", prefix + source,\n    ], timeout=timeout)\n    if result.returncode:\n        raise RuntimeError(\n            result.stderr.decode(\"utf-8\", errors=\"replace\").strip() or\n            \"PowerShell 종료 코드 \" + str(result.returncode)\n        )\n    return result.stdout.decode(\"utf-8-sig\", errors=\"replace\").strip()\n\n\ndef ps_quote(value):\n    return \"'\" + str(value).replace(\"'\", \"''\") + \"'\"\n\n\ndef query_json(source, timeout=60):\n    text = powershell(source, timeout)\n    if not text:\n        return []\n    value = json.loads(text)\n    return value if isinstance(value, list) else [value]\n\n\ndef redact(text):\n    text = str(text or \"\")\n    text = re.sub(\n        r\"(?i)((?:token|password|passwd|secret|api[_-]?key|authorization)\"\n        r\"\\s*(?:=|:|\\s)\\s*)(\\\"[^\\\"]*\\\"|'[^']*'|[^\\s;]+)\",\n        r\"\\1[REDACTED]\", text,\n    )\n    text = re.sub(r\"\\b\\d{6,12}:[A-Za-z0-9_-]{20,}\\b\", \"[TELEGRAM_TOKEN_REDACTED]\", text)\n    text = re.sub(r\"(https?://)[^/\\s:@]+:[^/\\s@]+@\", r\"\\1[REDACTED]@\", text)\n    return text\n\n\ndef command_argv(command):\n    if not command:\n        return []\n    shell32 = ctypes.WinDLL(\"shell32\", use_last_error=True)\n    kernel32 = ctypes.WinDLL(\"kernel32\", use_last_error=True)\n    shell32.CommandLineToArgvW.argtypes = [wintypes.LPCWSTR, ctypes.POINTER(ctypes.c_int)]\n    shell32.CommandLineToArgvW.restype = ctypes.POINTER(wintypes.LPWSTR)\n    kernel32.LocalFree.argtypes = [wintypes.HLOCAL]\n    kernel32.LocalFree.restype = wintypes.HLOCAL\n    count = ctypes.c_int()\n    pointer = shell32.CommandLineToArgvW(command, ctypes.byref(count))\n    if not pointer:\n        return []\n    try:\n        return [pointer[index] for index in range(count.value)]\n    finally:\n        kernel32.LocalFree(ctypes.cast(pointer, wintypes.HLOCAL))\n\n\ndef exact_project_script(command):\n    expected = {\n        os.path.normcase(os.path.abspath(str(ROOT / name))): name\n        for name in SCRIPT_NAMES\n    }\n    for argument in command_argv(command)[1:]:\n        if not os.path.isabs(argument):\n            continue\n        normalized = os.path.normcase(os.path.abspath(argument))\n        if normalized in expected:\n            return expected[normalized]\n    return None\n\n\ndef processes():\n    return query_json(\n        \"Get-CimInstance Win32_Process | \"\n        \"Select-Object ProcessId,ParentProcessId,Name,CommandLine,\"\n        \"@{n='Created';e={$_.CreationDate.ToUniversalTime().ToString('o')}} | \"\n        \"ConvertTo-Json -Depth 4 -Compress\"\n    )\n\n\ndef inspect_processes():\n    records = processes()\n    by_pid = {int(item[\"ProcessId\"]): item for item in records}\n    excluded = {os.getpid()}\n    current = os.getpid()\n    for _ in range(32):\n        parent = by_pid.get(current, {}).get(\"ParentProcessId\")\n        if not parent or int(parent) in excluded:\n            break\n        excluded.add(int(parent))\n        current = int(parent)\n\n    visible = []\n    candidates = []\n    log(\"\\n=== 콘솔 관련 프로세스 목록: 비밀 값은 마스킹 ===\")\n    for item in records:\n        if str(item.get(\"Name\", \"\")).lower() not in PROCESS_NAMES:\n            continue\n        clean = {\n            \"ProcessId\": item.get(\"ProcessId\"),\n            \"ParentProcessId\": item.get(\"ParentProcessId\"),\n            \"Name\": item.get(\"Name\"),\n            \"Created\": item.get(\"Created\"),\n            \"CommandLine\": redact(item.get(\"CommandLine\")),\n        }\n        visible.append(clean)\n        log(json.dumps(clean, ensure_ascii=False))\n        name = str(item.get(\"Name\", \"\")).lower()\n        target = exact_project_script(item.get(\"CommandLine\"))\n        if (\n            int(item[\"ProcessId\"]) not in excluded and target and\n            name in {\"python.exe\", \"pythonw.exe\", \"wscript.exe\", \"cscript.exe\"}\n        ):\n            candidates.append((item, target))\n\n    REPORT[\"processes\"] = visible\n    REPORT[\"excluded_self_and_ancestors\"] = sorted(excluded)\n    REPORT[\"stopped_processes\"] = []\n    if not candidates:\n        log(\"[확인] 정확히 식별된 프로젝트 종료 후보가 없습니다.\")\n        return\n\n    log(\"\\n종료 후보: \" + \", \".join(\n        \"{} PID={}\".format(name, item[\"ProcessId\"]) for item, name in candidates\n    ))\n    if not confirm(\"위 프로젝트 프로세스만 종료할까요? 자동 재기동하지 않습니다\"):\n        return\n\n    for original, target in candidates:\n        try:\n            pid = int(original[\"ProcessId\"])\n            current_records = processes()\n            current = next(\n                (item for item in current_records if int(item[\"ProcessId\"]) == pid), None\n            )\n            if current is None:\n                continue\n            if (\n                current.get(\"Created\") != original.get(\"Created\") or\n                current.get(\"CommandLine\") != original.get(\"CommandLine\")\n            ):\n                raise RuntimeError(\"PID 재사용 또는 프로세스 정보 변경\")\n            # PowerShell 내부에서도 시작 시각을 재확인한다.\n            source = (\n                \"$p=Get-CimInstance Win32_Process -Filter \" +\n                ps_quote(\"ProcessId=\" + str(pid)) + \";\"\n                \"if($null -ne $p){\"\n                \"$t=$p.CreationDate.ToUniversalTime().ToString('o');\"\n                \"if($t -ne \" + ps_quote(original[\"Created\"]) +\n                \"){throw 'PID identity changed'};\"\n                \"Stop-Process -Id \" + str(pid) + \" -ErrorAction Stop;\"\n                \"}\"\n            )\n            powershell(source)\n            REPORT[\"stopped_processes\"].append({\"pid\": pid, \"script\": target})\n            log(\"[종료] {} PID={}\".format(target, pid))\n        except Exception as error:\n            REPORT[\"warnings\"].append(\"프로세스 종료: \" + str(error))\n            log(\"[주의] \" + str(error))\n\n\ndef inspect_tasks_and_startup():\n    log(\"\\n=== 예약 작업·시작프로그램 점검 ===\")\n    try:\n        tasks = query_json(\n            \"Get-ScheduledTask | ForEach-Object {\"\n            \"$t=$_;\"\n            \"[pscustomobject]@{\"\n            \"TaskName=$t.TaskName;TaskPath=$t.TaskPath;State=[string]$t.State;\"\n            \"Actions=@($t.Actions | Select-Object Execute,Arguments,WorkingDirectory);\"\n            \"Triggers=@($t.Triggers | Select-Object StartBoundary,Enabled,\"\n            \"@{n='Interval';e={$_.Repetition.Interval}})\"\n            \"}} | ConvertTo-Json -Depth 8 -Compress\",\n            timeout=90,\n        )\n        relevant = []\n        for task in tasks:\n            serialized = json.dumps(task, ensure_ascii=False)\n            if str(ROOT).lower() in serialized.replace(\"\\\\\\\\\", \"\\\\\").lower() or re.search(\n                r\"rgon|omni|PT(?:1M|[1-5]S)\", serialized, re.I\n            ):\n                safe_task = json.loads(redact(serialized))\n                relevant.append(safe_task)\n                log(json.dumps(safe_task, ensure_ascii=False))\n        REPORT[\"relevant_scheduled_tasks\"] = relevant\n        log(\"[보존] 예약 작업은 자동 삭제·비활성화하지 않았습니다.\")\n    except Exception as error:\n        REPORT[\"warnings\"].append(\"예약 작업 조회: \" + str(error))\n\n    startup_dirs = [\n        Path(os.environ.get(\"APPDATA\", \"\")) /\n        \"Microsoft/Windows/Start Menu/Programs/Startup\",\n        Path(os.environ.get(\"PROGRAMDATA\", r\"C:\\ProgramData\")) /\n        \"Microsoft/Windows/Start Menu/Programs/Startup\",\n    ]\n    items = []\n    for directory in startup_dirs:\n        if directory.is_dir():\n            for path in directory.iterdir():\n                if path.is_file():\n                    record = {\"path\": str(path), \"bytes\": path.stat().st_size}\n                    items.append(record)\n                    log(\"[Startup] \" + str(path))\n    REPORT[\"startup_files\"] = items\n    try:\n        startup_commands = query_json(\n            \"Get-CimInstance Win32_StartupCommand | \"\n            \"Select-Object Name,Command,Location,User | ConvertTo-Json -Depth 4 -Compress\"\n        )\n        REPORT[\"startup_commands\"] = [\n            {key: redact(value) for key, value in item.items()}\n            for item in startup_commands\n        ]\n        for item in REPORT[\"startup_commands\"]:\n            log(\"[자동 시작] \" + json.dumps(item, ensure_ascii=False))\n    except Exception as error:\n        REPORT[\"warnings\"].append(\"자동 시작 명령 조회: \" + str(error))\n\n\ndef audit_sources():\n    log(\"\\n=== 소스 진단: 소스 파일 무수정 ===\")\n    findings = []\n    for name in (\"rgon_auto_watcher.py\", \"rgon_bridge_8765.py\"):\n        path = ROOT / name\n        if not path.is_file() or path.is_symlink():\n            continue\n        raw = path.read_bytes()\n        backup = REPORT_DIR / \"source_backups\" / name\n        atomic_write(backup, raw)\n        record = {\"file\": name, \"sha256\": hashlib.sha256(raw).hexdigest(), \"calls\": []}\n        try:\n            tree = ast.parse(raw.decode(\"utf-8-sig\"), filename=name)\n            for item in ast.walk(tree):\n                if not isinstance(item, ast.Call):\n                    continue\n                function = item.func\n                if not isinstance(function, ast.Attribute):\n                    continue\n                if (\n                    isinstance(function.value, ast.Name) and\n                    function.value.id == \"subprocess\" and\n                    function.attr in {\"run\", \"Popen\", \"call\", \"check_call\", \"check_output\"}\n                ):\n                    keywords = {keyword.arg for keyword in item.keywords if keyword.arg}\n                    call = {\n                        \"line\": item.lineno,\n                        \"function\": \"subprocess.\" + function.attr,\n                        \"creationflags_keyword\": \"creationflags\" in keywords,\n                        \"startupinfo_keyword\": \"startupinfo\" in keywords,\n                        \"note\": \"키워드 존재만 검사; 실제 값·별칭·래퍼의 동작은 미검증\",\n                    }\n                    record[\"calls\"].append(call)\n                    log(\"{}:{} {}\".format(name, item.lineno, json.dumps(call, ensure_ascii=False)))\n        except Exception as error:\n            record[\"parse_error\"] = str(error)\n        findings.append(record)\n    REPORT[\"source_audit\"] = findings\n    log(\n        \"[안전 경계] 네트워크 코드 접수→실행 큐 적재 및 자동 실행 watcher의 \"\n        \"패치·숨김 재기동은 수행하지 않습니다.\"\n    )\n\n\ndef find_chrome():\n    candidates = [\n        Path(os.environ.get(\"PROGRAMFILES\", r\"C:\\Program Files\")) /\n        \"Google/Chrome/Application/chrome.exe\",\n        Path(os.environ.get(\"PROGRAMFILES(X86)\", r\"C:\\Program Files (x86)\")) /\n        \"Google/Chrome/Application/chrome.exe\",\n        Path(os.environ.get(\"LOCALAPPDATA\", \"\")) /\n        \"Google/Chrome/Application/chrome.exe\",\n    ]\n    found = shutil.which(\"chrome.exe\")\n    if found:\n        candidates.insert(0, Path(found))\n    return next((path for path in candidates if path.is_file()), None)\n\n\ndef dashboard_shortcuts():\n    log(\"\\n=== 대시보드 바로가기 ===\")\n    if not DASHBOARD.is_file():\n        REPORT[\"dashboard\"] = {\"status\": \"MISSING\", \"path\": str(DASHBOARD)}\n        log(\"[미실행] rgon_alpha_audience.html이 없습니다. 다른 HTML로 임의 대체하지 않습니다.\")\n        return\n    chrome = find_chrome()\n    if not chrome:\n        REPORT[\"dashboard\"] = {\"status\": \"CHROME_NOT_FOUND\"}\n        log(\"[미실행] Chrome 실행 파일을 찾지 못했습니다.\")\n        return\n    desktop_text = powershell(\"[Environment]::GetFolderPath('Desktop')\")\n    desktop = Path(desktop_text)\n    if not desktop.is_dir():\n        raise RuntimeError(\"실제 Desktop 폴더를 찾지 못했습니다.\")\n    bat = desktop / \"👑_RGON_대시보드_열기.bat\"\n    shortcut = desktop / \"👑 RGON 대시보드 앱.lnk\"\n    for path in (bat, shortcut):\n        if path.exists():\n            atomic_write(REPORT_DIR / \"shortcut_backups\" / path.name, path.read_bytes())\n\n    uri = DASHBOARD.resolve().as_uri()\n    arguments = '--app=\"{}\" --window-size=1440,920'.format(uri)\n    # .bat는 ASCII 내용만 사용하므로 콘솔 코드페이지에 의존하지 않는다.\n    content = (\n        '@echo off\\r\\nstart \"\" \"' + str(chrome) + '\" ' + arguments + \"\\r\\n\"\n    )\n    try:\n        bat_bytes = content.encode(\"ascii\")\n    except UnicodeEncodeError:\n        # 비ASCII Chrome 경로에서는 UTF-8 코드페이지를 먼저 적용한다.\n        bat_bytes = (\n            \"@echo off\\r\\nchcp 65001 >nul\\r\\n\" + content\n        ).encode(\"utf-8\")\n    atomic_write(bat, bat_bytes)\n\n    script = (\n        \"$w=New-Object -ComObject WScript.Shell;\"\n        \"$s=$w.CreateShortcut(\" + ps_quote(shortcut) + \");\"\n        \"$s.TargetPath=\" + ps_quote(chrome) + \";\"\n        \"$s.Arguments=\" + ps_quote(arguments) + \";\"\n        \"$s.WorkingDirectory=\" + ps_quote(ROOT) + \";\"\n        \"$s.Description='RGON local dashboard';\"\n        \"$s.Save();\"\n    )\n    powershell(script)\n    if not shortcut.is_file():\n        raise RuntimeError(\"바로가기 생성 결과를 확인하지 못했습니다.\")\n\n    subprocess.Popen(\n        [str(chrome), \"--app=\" + uri, \"--window-size=1440,920\"],\n        cwd=str(ROOT), stdin=subprocess.DEVNULL,\n        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n        creationflags=NO_WINDOW,\n    )\n    REPORT[\"dashboard\"] = {\n        \"status\": \"LAUNCH_REQUESTED\",\n        \"file\": str(DASHBOARD), \"bat\": str(bat), \"shortcut\": str(shortcut),\n        \"note\": \"창 생성 요청 완료; 브라우저 렌더링 성공은 미검증\",\n    }\n    log(\"[오픈 요청] \" + uri)\n\n\ndef git_remote():\n    dotgit = ROOT / \".git\"\n    config = dotgit / \"config\"\n    if dotgit.is_file():\n        text = dotgit.read_text(encoding=\"utf-8-sig\").strip()\n        if text.startswith(\"gitdir:\"):\n            directory = Path(text.split(\":\", 1)[1].strip())\n            if not directory.is_absolute():\n                directory = ROOT / directory\n            config = directory / \"config\"\n    if not config.is_file():\n        REPORT[\"git_remotes\"] = []\n        return\n    parser = configparser.RawConfigParser(strict=False)\n    parser.read(config, encoding=\"utf-8\")\n    remotes = []\n    for section in parser.sections():\n        if section.startswith('remote \"'):\n            value = parser.get(section, \"url\", fallback=\"\")\n            try:\n                parsed = urllib.parse.urlsplit(value)\n                if parsed.scheme in {\"http\", \"https\"}:\n                    host = parsed.hostname or \"\"\n                    if parsed.port:\n                        host += \":\" + str(parsed.port)\n                    value = urllib.parse.urlunsplit(\n                        (parsed.scheme, host, parsed.path, \"\", \"\")\n                    )\n            except ValueError:\n                value = \"[URL 해석 실패; 비밀 보호를 위해 생략]\"\n            remotes.append({\"name\": section, \"url\": redact(value)})\n            log(\"[Git 원격] \" + section + \" \" + redact(value))\n    REPORT[\"git_remotes\"] = remotes\n\n\ndef archive_queues():\n    files = sorted({\n        path for pattern in (\"omni_*.py\", \"ahn_queue_*.txt\")\n        for path in ROOT.glob(pattern)\n        if path.is_file() and not path.is_symlink()\n        and path.resolve() != Path(__file__).resolve()\n    })\n    REPORT[\"archived_files\"] = []\n    if not files:\n        return\n    log(\"\\n=== 아카이브 후보 ===\")\n    for path in files:\n        log(path.name)\n    if not confirm(\n        \"위 파일을 실행 경로 밖의 backups/daily_omni_archive로 이동할까요? \"\n        \"omni_*.py에는 유지해야 할 도구가 포함될 수 있습니다\"\n    ):\n        return\n    destination = ROOT / \"backups\" / \"daily_omni_archive\" / STAMP\n    destination.mkdir(parents=True, exist_ok=False)\n    for path in files:\n        if path.stat().st_nlink > 1:\n            REPORT[\"warnings\"].append(\"하드 링크 아카이브 생략: \" + path.name)\n            continue\n        target = destination / path.name\n        raw = path.read_bytes()\n        atomic_write(target, raw)\n        if path.read_bytes() != raw:\n            REPORT[\"warnings\"].append(\"동시 변경으로 원본 유지: \" + path.name)\n            continue\n        path.unlink()\n        REPORT[\"archived_files\"].append({\n            \"name\": path.name, \"destination\": str(target),\n            \"sha256\": hashlib.sha256(raw).hexdigest(),\n        })\n\n\ndef memory_inventory():\n    log(\"\\n=== 기억·장부·인수인계 목록 ===\")\n    inventory = []\n    excluded = {\".git\", \"backups\", \"node_modules\", \".venv\", \"venv\", \"__pycache__\"}\n    for directory, directories, files in os.walk(ROOT, followlinks=False):\n        directories[:] = [\n            name for name in directories\n            if name not in excluded and not (Path(directory) / name).is_symlink()\n        ]\n        for name in files:\n            path = Path(directory) / name\n            if path.suffix.lower() not in {\".json\", \".md\", \".txt\"} or path.is_symlink():\n                continue\n            relative = path.relative_to(ROOT).as_posix()\n            if not re.search(\n                r\"memory|handover|state|brain|ledger|snapshot|constitution|schedule|\"\n                r\"기억|장부|인수인계\", relative, re.I\n            ):\n                continue\n            try:\n                item = {\"path\": relative, \"bytes\": path.stat().st_size}\n                inventory.append(item)\n                log(\"[기억] {} ({} bytes)\".format(relative, item[\"bytes\"]))\n            except OSError:\n                continue\n    REPORT[\"memory_inventory\"] = inventory\n\n\ndef heartbeat():\n    candidates = [\n        ROOT / \"rgon_agency_heartbeat.py\",\n        ROOT / \"scripts\" / \"rgon_agency_pulse.py\",\n    ]\n    path = next((item for item in candidates if item.is_file() and not item.is_symlink()), None)\n    if path is None:\n        REPORT[\"heartbeat\"] = {\"status\": \"MISSING\"}\n        return\n    if not confirm(\n        str(path.name) +\n        \"을 1회 실행할까요? 기존 파일의 외부 통신·내부 부작용은 본 정비기가 보증하지 않습니다\"\n    ):\n        REPORT[\"heartbeat\"] = {\"status\": \"SKIPPED\"}\n        return\n    try:\n        result = run_hidden([sys.executable, path], timeout=120)\n        text = redact(\n            result.stdout.decode(\"utf-8\", errors=\"replace\") + \"\\n\" +\n            result.stderr.decode(\"utf-8\", errors=\"replace\")\n        )\n        atomic_write(REPORT_DIR / \"heartbeat_output.txt\", (text or \"(출력 없음)\").encode(\"utf-8\"))\n        REPORT[\"heartbeat\"] = {\n            \"status\": \"PROCESS_COMPLETED\" if result.returncode == 0 else \"PROCESS_FAILED\",\n            \"returncode\": result.returncode,\n            \"health\": \"NOT_INFERRED_FROM_EXIT_CODE\",\n        }\n        log(\"[박동] 종료 코드 {} — 종료 코드만으로 ALL OK 판정하지 않음\".format(result.returncode))\n    except Exception as error:\n        REPORT[\"heartbeat\"] = {\"status\": \"ERROR\", \"error\": str(error)}\n\n\ndef make_summary():\n    lines = [\n        \"RGON 콘솔 깜빡임 정비·EOD 보고\",\n        \"시각: \" + datetime.datetime.now().astimezone().isoformat(timespec=\"seconds\"),\n        \"정확히 식별해 종료한 프로세스: {}개\".format(len(REPORT.get(\"stopped_processes\", []))),\n        \"예약 작업: {}개 검토 후보 / 자동 삭제·비활성화 없음\".format(\n            len(REPORT.get(\"relevant_scheduled_tasks\", []))\n        ),\n        \"대시보드: \" + REPORT.get(\"dashboard\", {}).get(\"status\", \"NOT_ATTEMPTED\"),\n        \"아카이브: {}개\".format(len(REPORT.get(\"archived_files\", []))),\n        \"박동: \" + REPORT.get(\"heartbeat\", {}).get(\"status\", \"NOT_ATTEMPTED\"),\n        \"기억 저장소: {}개\".format(len(REPORT.get(\"memory_inventory\", []))),\n        \"원인 확정: 미완료 — 반복 실행 주체와 재발 여부 추가 관측 필요\",\n        \"watcher/bridge: 소스 무수정·자동 재기동 없음\",\n        \"보안: 네트워크 코드→실행 큐 연결은 수정·활성화하지 않음\",\n        \"기억 저장소 목록:\",\n    ]\n    inventory = REPORT.get(\"memory_inventory\", [])\n    for item in inventory[:30]:\n        lines.append(\"- \" + item[\"path\"])\n    if len(inventory) > 30:\n        lines.append(\"- 나머지 {}개는 로컬 JSON 보고서 참조\".format(len(inventory) - 30))\n    if REPORT[\"warnings\"]:\n        lines.append(\"주의 사항: {}건 — 로컬 보고서 참조\".format(len(REPORT[\"warnings\"])))\n    return \"\\n\".join(lines)\n\n\ndef telegram(summary):\n    path = ROOT / \"rgon_telegram_bridge.py\"\n    if not path.is_file() or path.is_symlink():\n        REPORT[\"telegram\"] = {\"status\": \"MISSING\"}\n        return\n    if not confirm(\n        \"외부 발송: 위 요약과 기억 파일명 목록을 기존 텔레그램 수신처로 1회 전송할까요? \"\n        \"파일 내용·프로세스 명령줄은 전송하지 않습니다\"\n    ):\n        REPORT[\"telegram\"] = {\"status\": \"SKIPPED\"}\n        return\n    try:\n        result = run_hidden(\n            [sys.executable, path, \"--send-text\", summary[:3500]], timeout=45\n        )\n        REPORT[\"telegram\"] = {\n            \"status\": \"BRIDGE_PROCESS_COMPLETED\" if result.returncode == 0 else \"BRIDGE_PROCESS_FAILED\",\n            \"returncode\": result.returncode,\n            \"delivery\": \"NOT_INDEPENDENTLY_VERIFIED\",\n        }\n        log(\"[텔레그램] 브릿지 종료 코드: \" + str(result.returncode))\n    except subprocess.TimeoutExpired:\n        REPORT[\"telegram\"] = {\n            \"status\": \"DELIVERY_UNKNOWN\",\n            \"note\": \"타임아웃; 중복 발송 방지를 위해 자동 재시도하지 않음\",\n        }\n    except Exception as error:\n        REPORT[\"telegram\"] = {\"status\": \"ERROR\", \"error\": str(error)}\n\n\ndef main():\n    if os.name != \"nt\":\n        raise RuntimeError(\"Windows 전용 스크립트입니다.\")\n    if not ROOT.is_dir():\n        raise RuntimeError(\"프로젝트 폴더가 없습니다: \" + str(ROOT))\n    if hasattr(sys.stdout, \"reconfigure\"):\n        sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n    REPORT_DIR.mkdir(parents=True, exist_ok=False)\n    log(\"[안전 모드] 원인 후보 진단·확인된 정비만 수행합니다.\")\n    log(\"[제한] 자동 코드 실행 큐 패치·숨김 재기동·완전 박멸 보장은 제공하지 않습니다.\")\n\n    stages = [\n        (\"프로세스\", inspect_processes),\n        (\"예약·자동 시작\", inspect_tasks_and_startup),\n        (\"소스 진단\", audit_sources),\n        (\"대시보드\", dashboard_shortcuts),\n        (\"Git 원격\", git_remote),\n        (\"큐 아카이브\", archive_queues),\n        (\"기억 목록\", memory_inventory),\n        (\"박동\", heartbeat),\n    ]\n    for label, action in stages:\n        try:\n            action()\n        except Exception as error:\n            message = label + \": \" + str(error)\n            REPORT[\"warnings\"].append(message)\n            log(\"[주의] \" + message)\n\n    summary = make_summary()\n    log(\"\\n\" + summary)\n    atomic_write(REPORT_DIR / \"eod_report.txt\", summary.encode(\"utf-8\"))\n    atomic_write(REPORT_DIR / \"doctor_report.json\", encoded_json(REPORT))\n\n    telegram(summary)\n    REPORT[\"finished_at\"] = datetime.datetime.now().astimezone().isoformat()\n    atomic_write(REPORT_DIR / \"doctor_report.json\", encoded_json(REPORT))\n    log(\"\\n[보고서] \" + str(REPORT_DIR))\n    log(\n        \"[정비 종료] 수행 내역을 기록했습니다. \"\n        \"깜빡임 재발 시 예약 작업·부모 프로세스를 추가 추적해야 하며, 완전 해결로 단정하지 않습니다.\"\n    )\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except KeyboardInterrupt:\n        print(\"\\n[중단] 이미 수행된 조치는 보고서 폴더를 확인하세요.\", file=sys.stderr)\n        sys.exit(130)\n    except Exception as error:\n        print(\"[DOCTOR FAILED] \" + str(error), file=sys.stderr)\n        sys.exit(1)\nCopy","lang":"python","kind":"code","lines":712,"bytes":27968,"funcs":["log","atomic_write","encoded_json","confirm","hidden_options","run_hidden","powershell_exe","powershell","ps_quote","query_json","redact","command_argv","exact_project_script","processes","inspect_processes","inspect_tasks_and_startup","audit_sources","find_chrome","dashboard_shortcuts","git_remote","archive_queues","memory_inventory","heartbeat","make_summary","telegram","main"],"funcCount":26,"tryCount":14,"hasEntry":true,"score":118,"blockCount":15,"hash":"3147885466","ts":1792675755904,"url":"https://www.genspark.ai/agents?id=c3af208d-11ca-4822-87b5-37d0f4731569","title":"자가 진화 AI 에이전트 표준 매뉴얼 SOP 검수 요청","role":"gpt"}}